const chatInput = $('Chat input1').first().json.chat_input.trim();
const parts = chatInput.split(' ');
const cmd = parts[0].toUpperCase();
const numero = parts[1] ? parts[1].trim() : '';
const resto = parts.slice(2).join(' ');

let accion = 'DESCONOCIDO';
let parametro = '';
let nota = '';

if (cmd === 'PAUSAR' && numero) { accion = 'PAUSAR'; parametro = numero; }
else if (cmd === 'ACTIVAR' && numero) { accion = 'ACTIVAR'; parametro = numero; }
else if (cmd === 'LISTA') { accion = 'LISTA'; }
else if (cmd === 'NOTA' && numero) { accion = 'NOTA'; parametro = numero; nota = resto; }

return [{ json: { accion, parametro, nota } }];

const accion = $('Parsear comando').first().json.accion;
const parametro = $('Parsear comando').first().json.parametro;

let text = '';

if (accion === 'PAUSAR') {
  text = '✅ Lead ' + parametro + ' pasado a modo HUMANO. El bot no va a responder más hasta que lo actives.';
} else if (accion === 'ACTIVAR') {
  text = '✅ Lead ' + parametro + ' activado. El bot retoma la conversación.';
} else if (accion === 'NOTA') {
  text = '✅ Nota guardada para ' + parametro + '.';
} else if (accion === 'LISTA') {
  const items = $input.all();
  if (!items || items.length === 0) {
    text = '📋 No hay leads activos en este momento.';
  } else {
    const lista = items.map((i, idx) => 
      (idx + 1) + '. ' + (i.json.Nombre || 'Sin nombre') + ' — ' + i.json.WhatsApp
    ).join('\n');
    text = '📋 Leads activos:\n' + lista;
  }
}

return [{ json: { text } }];

const items = $input.all();
let text = items[0]?.json?.output || '';

// Limpiar markdown
text = text.trim();
text = text.replace(/```[\s\S]*?```/g, '');
text = text.replace(/[*_#>`]/g, '');
text = text.replace(/\s+/g, ' ').trim();

return [{ json: { text } }];

const agentOutput = $('AI Agent').first().json.output || '';
const nombre = $('Normalizacion1').first().json.user.name || 'Lead';
const whatsapp = $('Normalizacion1').first().json.message.chat_id.replace('@s.whatsapp.net','');

// Datos del inmueble desde Sheets (vienen del nodo Buscar lead en Sheets)
const leadData = $('Releer lead actualizado').first().json;
const tipoInmueble = leadData['Tipo inmueble'] || 'Sin datos';
const zona = leadData['Zona'] || 'Sin datos';
const superficie = leadData['Superficie m²'] || 'Sin datos';

const notif = '🔥 Lead listo para cerrar:\n' +
              '👤 ' + nombre + '\n' +
              '📱 ' + whatsapp + '\n' +
              '🏠 ' + tipoInmueble + ' en ' + zona + '\n' +
              '📐 ' + superficie + ' m²';

const textoLead = agentOutput.replace('##LISTO_PARA_CERRAR##', '').trim();

return [{ json: { texto_lead: textoLead, notif_encargado: notif } }];

const fromMe = $('Normalizacion1').first().json.message.from_me;
const chatId = $('Normalizacion1').first().json.message.chat_id.replace('@s.whatsapp.net','');
const encargadoNumero = '5492615254816';

let origen = '';

if (chatId === encargadoNumero) {
  origen = 'ENCARGADO_COMANDO';
} else if (fromMe === true || fromMe === 'true') {
  origen = 'ENCARGADO_AL_LEAD';
} else {
  origen = 'LEAD';
}

return [{ json: { ...$input.first().json, origen } }];
